package cose

import (
	"bytes"
	"crypto/ecdh"
	"encoding/hex"
	"encoding/json"
	"errors"
	"os"
	"testing"
)

// legacyV022 holds messages produced by corecbor v0.2.2 (proposal 029):
// testdata/legacy-v0.2.2/encryption.json, generated by running EncryptMulti
// and ComputeMACMulti from the v0.2.2 tag with the keys below.
type legacyV022 struct {
	P256D, Plaintext                         string
	EncryptPBES2, EncryptECDHES, EncryptHPKE string
	MACPBES2, MACECDHES                      string
}

func loadLegacyV022(t *testing.T) (legacyV022, *ecdh.PrivateKey) {
	t.Helper()
	b, err := os.ReadFile("testdata/legacy-v0.2.2/encryption.json")
	if err != nil {
		t.Fatal(err)
	}
	var raw map[string]string
	if err := json.Unmarshal(b, &raw); err != nil {
		t.Fatal(err)
	}
	f := legacyV022{
		P256D: raw["p256_d"], Plaintext: raw["plaintext"],
		EncryptPBES2: raw["encrypt_pbes2"], EncryptECDHES: raw["encrypt_ecdh_es"], EncryptHPKE: raw["encrypt_hpke"],
		MACPBES2: raw["mac_pbes2"], MACECDHES: raw["mac_ecdh_es"],
	}
	d, _ := hex.DecodeString(f.P256D)
	priv, err := ecdh.P256().NewPrivateKey(d)
	if err != nil {
		t.Fatal(err)
	}
	return f, priv
}

func legacyPBES2() *PBES2Key {
	return &PBES2Key{Password: []byte("v0.2.2 password"), Salt: bytes.Repeat([]byte{0x5a}, 16), Count: 1000}
}

func mustHex(t *testing.T, s string) []byte {
	t.Helper()
	b, err := hex.DecodeString(s)
	if err != nil {
		t.Fatal(err)
	}
	return b
}

func TestCompatLegacyEncryption(t *testing.T) {
	f, priv := loadLegacyV022(t)
	cases := []struct {
		name   string
		wire   string
		r      KeyDeriver
		legacy EncryptOption
	}{
		{"pbes2", f.EncryptPBES2, legacyPBES2(), WithLegacyPBES2Labels()},
		{"ecdh-es", f.EncryptECDHES, &ECDHESKey{PrivateKey: priv}, WithLegacyECDHES()},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			msg, err := UnmarshalEncrypt(mustHex(t, c.wire))
			if err != nil {
				t.Fatal(err)
			}
			if _, err := DecryptMulti(msg, c.r, 0); !errors.Is(err, ErrUnsupportedAlgorithm) {
				t.Fatalf("without selector = %v, want ErrUnsupportedAlgorithm", err)
			}
			for _, opt := range []EncryptOption{c.legacy, CompatV02Encryption()} {
				if pt, err := DecryptMulti(msg, c.r, 0, opt); err != nil || string(pt) != f.Plaintext {
					t.Fatalf("with selector = %q, %v", pt, err)
				}
			}
		})
	}
	// v0.2.2 HPKE (alg 35) needs no selector.
	msg, err := UnmarshalEncrypt(mustHex(t, f.EncryptHPKE))
	if err != nil {
		t.Fatal(err)
	}
	if pt, err := DecryptMulti(msg, &HPKEKey{PrivateKey: priv}, 0); err != nil || string(pt) != f.Plaintext {
		t.Fatalf("HPKE = %q, %v", pt, err)
	}
}

func TestCompatLegacyMAC(t *testing.T) {
	f, priv := loadLegacyV022(t)
	msg, err := UnmarshalMac(mustHex(t, f.MACPBES2))
	if err != nil {
		t.Fatal(err)
	}
	if err := VerifyMACMulti(msg, legacyPBES2(), 0); !errors.Is(err, ErrUnsupportedAlgorithm) {
		t.Fatalf("v0.2 PBES2 MAC without selector = %v, want ErrUnsupportedAlgorithm", err)
	}
	if err := VerifyMACMulti(msg, legacyPBES2(), 0, WithLegacyMACPBES2Labels()); err != nil {
		t.Fatalf("WithLegacyMACPBES2Labels: %v", err)
	}
	// v0.2.2's ECDHESKey.WrapKey discarded the MAC key, so its ECDH-ES
	// MAC messages never verified, in v0.2.2 or now.
	msg, err = UnmarshalMac(mustHex(t, f.MACECDHES))
	if err != nil {
		t.Fatal(err)
	}
	if err := VerifyMACMulti(msg, &ECDHESKey{PrivateKey: priv}, 0); err == nil {
		t.Fatal("v0.2 ECDH-ES MAC verified")
	}
}
